using DevExpress.XtraGrid.Views.Grid;
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace rec_inven_samp
{
    public partial class ctrl_rds : UserControl
    {
        public ctrl_rds()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource asynchronously
            sqlDataSource1.FillAsync();

            grid_unselect();
        }

        private void gridControl1_Click(object sender, EventArgs e)
        {
            // Disable appearance settings that paint the focused row.
            gridView1.OptionsSelection.EnableAppearanceFocusedRow = true;
            // Hide the focused rectangle.
            gridView1.FocusRectStyle = DrawFocusRectStyle.RowFocus;
            // Hide the row indicator.
            //gridView1.OptionsView.ShowIndicator = true;
        }

        private void grid_unselect()
        {
            // Disable appearance settings that paint the focused row.
            gridView1.OptionsSelection.EnableAppearanceFocusedRow = false;
            // Hide the focused rectangle.
            gridView1.FocusRectStyle = DrawFocusRectStyle.None;
            // Hide the row indicator.
            //gridView1.OptionsView.ShowIndicator = false;
        }

        private void gridControl1_Leave(object sender, EventArgs e)
        {
            grid_unselect();
        }

        private void ctrl_rds_Click(object sender, EventArgs e)
        {
            //grid_unselect();
            ActiveControl = null;
        }
    }
}
